    refundMethod: 'cash' | 'cliq';
    stockDisposition: 'restock' | 'damaged';
    count: number;
    amount: number;
  }>;
  /** Owner withdrawals booked in this shift's drawer (migration 181). */
  ownerWithdrawals?: {
    net: number;
    netMovementAfterWithdrawals?: number;
    withdrawn: number;
    returned: number;
    items: Array<{ kind: 'withdrawal' | 'return'; withdrawalNumber: string; amount: number; at: string; originalShiftNumber?: string }>;
  };
  returnQuantityBreakdown?: Array<{
    eventId: string;
    productId: string;
    productName: string;
    sellableQuantity: number;
    defectQuantity: number;
    customerDamageQuantity: number;
  }>;
}

